    {
        const unsigned char* p = (const unsigned char*)data;
        bytes.insert(bytes.end(), p, p + length);
    }
    void WriteULong(unsigned long value)
    {
        unsigned int v = (unsigned int)value;
        Write(&v, 4);
    }
